import{c as t,Q as o,j as n,m as r}from"./chunks/framework.BqPkuuVc.js";const g=JSON.parse('{"title":"Walkthrough: your first event","description":"","frontmatter":{},"headers":[],"relativePath":"user/getting-started/first-event-walkthrough.md","filePath":"user/getting-started/first-event-walkthrough.md"}'),a={name:"user/getting-started/first-event-walkthrough.md"};function s(i,e,l,h,d,c){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="walkthrough-your-first-event" tabindex="-1">Walkthrough: your first event <a class="header-anchor" href="#walkthrough-your-first-event" aria-label="Permalink to &quot;Walkthrough: your first event&quot;">​</a></h1><p><strong>Audience:</strong> New users — an organiser or timing operator trying Manager for the first time.</p><p>An end-to-end tour: create a small event, add some data, download a card, and view results. Everything a real event needs, but small enough to do in an afternoon at home. Each step links to a deeper page if you want the full details.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>You&#39;ll need:</p><ul><li><strong>Manager installed and running</strong> on one computer (the &quot;server&quot;). See <a href="./../download-and-install/">Installing meshO Manager</a> if you haven&#39;t done this yet.</li><li><strong>A web browser</strong> on the same computer, or on any other device on the same network. <strong>Chrome, Edge or Firefox 151+ is required</strong> if you want to download cards or use the Station Memory tool — both rely on Web Serial, which Safari and older Firefox don&#39;t support. For everything else, any modern browser works.</li><li><strong>Optionally</strong>, a SportIdent USB reader station (BSM7-USB or BSM8-USB) and one or two cards, if you want to test card download. You can skip the download steps if you don&#39;t have the hardware — everything else works without it.</li></ul><blockquote><p><strong>Tip:</strong> You don&#39;t need meshO Prime, radio controls, or a course in the forest to complete this walkthrough. Those are covered in <a href="./../running-the-event/connecting-prime-and-radios">Connecting meshO Prime and radios</a>.</p></blockquote><h2 id="the-states-of-an-event" tabindex="-1">The states of an event <a class="header-anchor" href="#the-states-of-an-event" aria-label="Permalink to &quot;The states of an event&quot;">​</a></h2><p>Every event in Manager moves through these states:</p><ol><li><strong>Setup mode</strong> — the event is being built. You configure classes, courses, controls, competitors, and start times.</li><li><strong>Event in progress</strong> — the event is running. Card downloads work, radio punches flow in, and results are calculated in real time. The <strong>event date</strong> becomes locked; everything else — competitors, classes, start times, course assignments — remains editable, so late entries and on-the-day corrections still work.</li><li><strong>Event completed</strong> — the event is done. You can still view and export everything.</li><li><strong>Event abandoned</strong> — the event was started but never finished cleanly (e.g. cancelled due to weather).</li></ol><p>You transition between states with a single button in the app bar at the top of the screen (<strong>Start event</strong> to begin, <strong>Finish event</strong> to complete). The current state is shown as a coloured chip next to the event name.</p><h2 id="_1-open-manager" tabindex="-1">1. Open Manager <a class="header-anchor" href="#_1-open-manager" aria-label="Permalink to &quot;1. Open Manager&quot;">​</a></h2><p>Open your browser and navigate to the Manager URL. If you&#39;re on the server PC itself, this is usually <code>http://localhost:5154/manager</code> (the default — the port can be changed in <strong>Settings → Server</strong>).</p><p>You&#39;ll land on the <strong>Events</strong> page. If this is a fresh install, you&#39;ll see a welcome message: <strong>&quot;Welcome to meshO Manager&quot;</strong> with a <strong>New Event</strong> button — and, when the installation ships example events, <strong>Try a sample event</strong> beside it.</p><h2 id="a-shortcut-add-a-sample-event" tabindex="-1">A shortcut: add a sample event <a class="header-anchor" href="#a-shortcut-add-a-sample-event" aria-label="Permalink to &quot;A shortcut: add a sample event&quot;">​</a></h2><p>If you&#39;d rather look at a finished event than build one, click <strong>Try a sample event</strong> and then <strong>Add</strong>. (Once you have events of your own, the same list is behind the <strong>Sample events</strong> button in the row above the event tabs.)</p><p>Manager ships with complete example events — real classes, courses, competitors, card downloads and results. Adding one puts a copy in your event list, dated today, exactly as though you had run it yourself: browse the results and splits, print splits, put a screen up, or use <strong>Replay</strong> to watch the event unfold as if it were happening now (see <a href="./../running-the-event/dashboard">The event dashboard</a>). Change it or delete it whenever you like — it&#39;s an ordinary event and affects nothing else.</p><p>Adding a sample is the fastest way to see what a finished event looks like. Come back here afterwards to build one of your own.</p><h2 id="_2-create-an-event" tabindex="-1">2. Create an event <a class="header-anchor" href="#_2-create-an-event" aria-label="Permalink to &quot;2. Create an event&quot;">​</a></h2><p>Click <strong>New Event</strong>. Manager creates the event immediately with sensible defaults (e.g. individual start) and takes you straight to its <strong>Dashboard</strong>.</p><p>By default the event is named after today&#39;s day of the week (e.g. &quot;Thursday event&quot;) and dated today. To rename it to something more recognisable like &quot;Test Event&quot;:</p><ol><li>On the dashboard, click the edit icon on the <strong>Event header</strong> card.</li><li>Change <strong>Event name</strong> (and date, if you want a future date).</li><li>Save.</li></ol><blockquote><p><strong>Shortcut — import from Eventor:</strong> If your organisation uses Eventor and you&#39;ve already configured the connection in <strong>Settings → Eventor</strong>, you can click <strong>New from Eventor</strong> instead. Manager will fetch a list of upcoming events, let you pick one, and import classes, competitors, clubs, and start times in one step. If you go this route, you can skip ahead to <a href="#6-explore-the-dashboard">step 6 (the dashboard)</a>. See <a href="./../event-setup/create-event-from-eventor">Creating an event from Eventor</a> for the full details.</p></blockquote><h2 id="_3-create-a-course" tabindex="-1">3. Create a course <a class="header-anchor" href="#_3-create-a-course" aria-label="Permalink to &quot;3. Create a course&quot;">​</a></h2><p>Before you start the event, you need at least one course. For this test, you&#39;ll make a short one.</p><ol><li>Open the <strong>Courses</strong> page from the left navigation menu.</li><li>Click <strong>Add</strong>.</li><li>In the dialog, give the course a name — for example &quot;Short&quot;.</li><li>In the <strong>Controls</strong> field, type each control code and press <strong>Enter</strong> after each one. For example, type <code>31</code>, Enter, <code>32</code>, Enter, <code>33</code>, Enter. The controls appear as chips that you can drag to reorder.</li><li>Click <strong>Save</strong>.</li></ol><p>You now have a 3-control course. The controls are created automatically as you add them.</p><blockquote><p><strong>Tip:</strong> In a real event, you&#39;d typically import courses from a Purple Pen file or IOF XML rather than typing them by hand. See <a href="./../event-setup/classes-and-courses">Classes and courses</a>.</p></blockquote><h2 id="_4-create-a-class-and-assign-the-course" tabindex="-1">4. Create a class and assign the course <a class="header-anchor" href="#_4-create-a-class-and-assign-the-course" aria-label="Permalink to &quot;4. Create a class and assign the course&quot;">​</a></h2><p>A <em>class</em> is a category of competitors (e.g. M21E, W18A). A class typically runs a single course — although more than one can be assigned if you need it.</p><ol><li>Open the <strong>Classes</strong> page from the navigation menu.</li><li>Click <strong>Add</strong>.</li><li>Enter a class name — for example &quot;Open&quot;.</li><li>In the <strong>Courses</strong> dropdown, select the &quot;Short&quot; course you just created.</li><li>Click <strong>Save</strong>.</li></ol><h2 id="_5-add-a-few-competitors" tabindex="-1">5. Add a few competitors <a class="header-anchor" href="#_5-add-a-few-competitors" aria-label="Permalink to &quot;5. Add a few competitors&quot;">​</a></h2><ol><li>Open the <strong>Competitors</strong> page from the navigation menu.</li><li>Click <strong>Add</strong> (or use the <strong>Actions</strong> menu → <strong>Add</strong>).</li><li>Fill in a competitor name and assign them to the &quot;Open&quot; class.</li><li>If you have a card, enter its number in the <strong>Card</strong> field. Otherwise leave it blank for now.</li><li>Save, and repeat for one or two more competitors.</li></ol><p>You should now see your competitors listed with their class, and a status of &quot;None&quot; (they haven&#39;t started yet).</p><blockquote><p><strong>Tip:</strong> In a real event, competitors and their card numbers come from the entry system (Eventor, IOF XML import, or on-the-day registration). Typing them by hand is only needed for small events or late entries. See <a href="./../event-setup/competitors-clubs-teams">Competitors, clubs and teams</a>.</p></blockquote><h2 id="_6-explore-the-dashboard" tabindex="-1">6. Explore the dashboard <a class="header-anchor" href="#_6-explore-the-dashboard" aria-label="Permalink to &quot;6. Explore the dashboard&quot;">​</a></h2><p>Navigate back to the event <strong>Dashboard</strong> (click the dashboard icon in the side menu).</p><p>The dashboard is your central view during an event. You&#39;ll see several cards:</p><ul><li><strong>Event header</strong> — the event name, date, and status chip. Click the edit icon to change event details.</li><li><strong>Event summary</strong> — shows competitor counts by status (not started, in forest, finished, etc.). Right now everyone should show as &quot;not started&quot;.</li><li><strong>Quick Competitor Actions</strong> — a quick-search panel where you can look up any competitor, view their details, change their card number, or reassign them to a different class on the fly. You can also add a new competitor from here.</li><li><strong>Download Card</strong> — a shortcut into the Card download station.</li><li><strong>Spectator analytics</strong> — once the event is live and screens are being watched, this shows how many spectators are connected to the live screens.</li></ul><p>Other cards appear depending on your event configuration:</p><ul><li><strong>Field units status</strong> — when meshO Prime is connected.</li><li><strong>Radio punch forwarding / listening</strong> — only when those features are enabled in <strong>Settings → Radio Punch Forwarding</strong> / <strong>Listening</strong>.</li><li><strong>Splits printer</strong> — when a splits printer is configured.</li><li><strong>Extension tiles</strong> — any tiles contributed by installed extensions.</li></ul><p>Don&#39;t worry about the conditional cards for this test.</p><p>For the full tour of every dashboard card, see <a href="./../running-the-event/dashboard">The event dashboard</a>.</p><h2 id="_7-start-the-event" tabindex="-1">7. Start the event <a class="header-anchor" href="#_7-start-the-event" aria-label="Permalink to &quot;7. Start the event&quot;">​</a></h2><p>Downloads, radio punches, and live results only happen once the event is in progress. Right now your event is still in <strong>Setup mode</strong>.</p><p>In the app bar at the top of the screen, click <strong>Start event</strong>. Manager will check your event for problems (missing courses, classes with no competitors, etc.), and if everything looks good, transitions the event to <strong>Event in progress</strong>. The status chip next to the event name changes, and the <strong>Start event</strong> button is replaced with a <strong>Finish event</strong> button (for later).</p><blockquote><p><strong>Tip:</strong> If Manager detects a problem you&#39;ll get an alert to tell you what&#39;s missing. Fix the issue, then click <strong>Start event</strong> again.</p></blockquote><h2 id="_8-download-a-card" tabindex="-1">8. Download a card <a class="header-anchor" href="#_8-download-a-card" aria-label="Permalink to &quot;8. Download a card&quot;">​</a></h2><blockquote><p><strong>Skip this step</strong> if you don&#39;t have a SportIdent USB reader and a card.</p><p><strong>Browser requirement:</strong> this step needs Chrome, Edge or Firefox 151+ — the SI reader uses the Web Serial API, which Safari and older Firefox don&#39;t support.</p></blockquote><p>This is the core during-event action: a competitor finishes, hands in their card, and you read it.</p><ol><li>Open the <strong>Download Card</strong> page from the navigation menu.</li><li>You&#39;ll see a prompt: <strong>&quot;Connect SportIdent Reader&quot;</strong> with a <strong>Select Device</strong> button.</li><li>Plug your SI reader into a USB port, then click <strong>Select Device</strong>. Your browser will show a system dialog listing available serial devices — pick the SportIdent reader and confirm.</li><li>The status changes to <strong>Listening</strong> (green chip). The page now says <strong>&quot;Insert SportIdent Card&quot;</strong>.</li></ol><p>Now insert the card in the reader:</p><ul><li>A progress bar appears while the card is read.</li><li>If the card number matches a competitor you entered in step 5, you&#39;ll see a green <strong>OK</strong> banner with the competitor&#39;s name, class, and result.</li><li>If the card number doesn&#39;t match anyone, you&#39;ll see an orange <strong>Unassigned</strong> banner. Manager gives you the option to assign it to an existing competitor or create a new one right there.</li><li>If the card is missing a required punch, you&#39;ll see a <strong>Missing Punch (MP)</strong> result. You can change the competitor&#39;s class to one where the punches are valid, or override the status later.</li></ul><p>The right side of the page shows a <strong>download history table</strong> with every card you&#39;ve read — searchable and filterable by status.</p><p>For the full details on every download scenario, see <a href="./../running-the-event/card-download">Downloading cards</a>.</p><h2 id="_9-see-radio-punches-optional" tabindex="-1">9. See radio punches (optional) <a class="header-anchor" href="#_9-see-radio-punches-optional" aria-label="Permalink to &quot;9. See radio punches (optional)&quot;">​</a></h2><p>If you have meshO Prime connected with radio controls in the field, the <strong>Radio Punches</strong> page shows punches arriving in real time — a table of SI number, competitor name, control code, and punch time, with the most recent at the top.</p><p>For this at-home test you probably don&#39;t have a radio network, so feel free to skip this. See <a href="./../running-the-event/radio-punches">Radio punches</a> and <a href="./../running-the-event/connecting-prime-and-radios">Connecting meshO Prime and radios</a> when you&#39;re ready for the real thing.</p><h2 id="_10-watch-the-leaderboard" tabindex="-1">10. Watch the leaderboard <a class="header-anchor" href="#_10-watch-the-leaderboard" aria-label="Permalink to &quot;10. Watch the leaderboard&quot;">​</a></h2><p>During an event, the <strong>Leaderboard</strong> is how everyone follow things as they unfold. It updates live: every radio punch, every card download, every status change appears the moment it happens. No refreshing, no re-running a report.</p><p>From the <strong>Screens</strong> page in the navigation menu, open the default <strong>All classes</strong> screen. The leaderboard opens in a new tab, showing every class with the current finishers, who&#39;s still out, and how the order has changed as new results come in. This is the view you&#39;d put on a TV at the arena, or keep open on a second screen while you work.</p><p>For more on screens and their configuration, see <a href="./../screens/creating-screens">Creating Leaderboard screens</a> and <a href="./../screens/tv-screens">TV screens</a>.</p><h2 id="_11-view-the-results" tabindex="-1">11. View the results <a class="header-anchor" href="#_11-view-the-results" aria-label="Permalink to &quot;11. View the results&quot;">​</a></h2><p>The <strong>Results</strong> page is the operator&#39;s view of the same data — detailed, filterable, built for checking and exporting rather than live display.</p><p>Open the <strong>Results</strong> page from the navigation menu. You&#39;ll see results grouped by class.</p><p>For each class, competitors are listed in finishing order with their time. Competitors who haven&#39;t finished yet (or who have a problem status like MP or DNF) appear below the finishers.</p><p>Use the filter panel on the right to:</p><ul><li><strong>Group by</strong> class or course.</li><li><strong>Filter</strong> to specific classes or clubs.</li><li><strong>Show behind time</strong> to see the gap to the leader.</li><li><strong>Include / exclude</strong> specific statuses (DNS, In Forest, etc.). These change what <em>you</em> see on screen only — an exported results file always accounts for everyone who took part, whatever is ticked here. See <a href="./../reference/status-and-race-time#what-an-exported-results-file-contains">What an exported results file contains</a>.</li></ul><p>When you&#39;re ready to share results:</p><ul><li>Click <strong>Publish → Upload to Eventor</strong> to send results straight to Eventor from within Manager.</li><li>Click <strong>Publish → Export IOF XML</strong> to download a results file for other systems (or to upload to Eventor by hand).</li><li>Click <strong>Publish → Print view</strong> to get a printable version.</li></ul><p>For the full details, see <a href="./../after-the-event/results">Results</a>.</p><h2 id="_12-what-s-next" tabindex="-1">12. What&#39;s next <a class="header-anchor" href="#_12-what-s-next" aria-label="Permalink to &quot;12. What&#39;s next&quot;">​</a></h2><p>You&#39;ve just walked through the core loop of meshO Manager — create an event, define its structure, register competitors, download cards, and view results. A real event adds more layers:</p><ul><li><strong>Importing data</strong> from Eventor, IOF XML, or Purple Pen so you don&#39;t type everything by hand. See <a href="./../event-setup/import-event-data">Importing event data</a>.</li><li><strong>Connecting meshO Prime</strong> to get live radio punches from controls in the forest. See <a href="./../running-the-event/connecting-prime-and-radios">Connecting meshO Prime and radios</a>.</li><li><strong>Setting up spectator screens</strong> on TVs at the arena. See <a href="./../screens/creating-screens">Creating Leaderboard screens</a> and <a href="./../screens/tv-screens">TV screens</a>.</li><li><strong>Running commentary</strong> for the announcer. See <a href="./../screens/commentary">Commentary</a>.</li><li><strong>Handling problems</strong> — missing punches, unknown cards, overdue competitors. See <a href="./../running-the-event/resolving-issues">Resolving issues on the day</a>.</li><li><strong>Multiple operators</strong> working simultaneously on different laptops. See <a href="./../reference/multi-operator-setup">Multi-operator setup</a> — remember, Manager is multi-user by default. Other volunteers just open the same URL in their browser.</li></ul><p>Before your first real competition, work through the <a href="./../event-setup/pre-event-checklist">Pre-event checklist</a> to make sure nothing is forgotten.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../what-is-mesho-manager/">How meshO Manager works</a> — the architecture behind what you just used.</li><li><a href="./../download-and-install/">Installing meshO Manager</a></li><li><a href="./concepts-glossary">Concepts and glossary</a></li><li>All the &quot;Event setup&quot; and &quot;Running the event&quot; pages expand on individual steps of this walkthrough.</li></ul>',77)])])}const p=t(a,[["render",s]]);export{g as __pageData,p as default};
